const showToast=(text)=>{document.querySelectorAll('.toast-lite').forEach(t=>t.remove());const t=document.createElement('div');t.className='toast-lite';t.textContent=text;document.body.appendChild(t);setTimeout(()=>t.remove(),1800)};
document.querySelectorAll('.kebab').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();document.querySelectorAll('.action-cell.menu-open').forEach(cell=>{if(cell!==btn.closest('.action-cell'))cell.classList.remove('menu-open')});btn.closest('.action-cell').classList.toggle('menu-open');document.body.classList.toggle('menu-active',!!document.querySelector('.action-cell.menu-open'))}));
document.addEventListener('click',e=>{if(!e.target.closest('.action-cell'))document.querySelectorAll('.action-cell.menu-open').forEach(cell=>cell.classList.remove('menu-open'));document.body.classList.remove('menu-active')});
document.getElementById('refreshRoles')?.addEventListener('click',()=>showToast('Roles refreshed'));
document.getElementById('clearFilters')?.addEventListener('click',()=>{document.querySelectorAll('.filter-chip').forEach(chip=>chip.remove());showToast('Filters cleared')});
document.getElementById('closeAudit')?.addEventListener('click',()=>document.querySelector('.audit')?.classList.add('is-hidden'));
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('.searchbox input')?.focus()}if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();document.querySelector('.role-search input')?.focus()}});
</script>
